"use client";

/**
 * GameLogo — the single per-game brand mark used everywhere a game identity is
 * shown across Nxeon: the marketing /game-servers grid + per-game pricing rows,
 * the per-game SEO landing heroes (GameLandingPage), the PricingExplorer game
 * sub-tabs, and the customer deploy picker (GameDeploy). It replaces the old
 * generic 🎮 emoji / gradient placeholders with the real logo, and gracefully
 * falls back so a surface is never blank.
 *
 * ── Drop-in convention (PRIMARY, owner-supplied official logos) ──────────────
 * The owner drops official logos at:
 *     public/logos/games/<family>.svg   ← preferred
 *     public/logos/games/<family>.png   ← also accepted (raster)
 * where <family> is one of the six canonical GAME_FAMILIES (lib/games.ts):
 *     minecraft.svg  valheim.svg  rust.svg  palworld.svg  cs2.svg  terraria.svg
 * Drop a file at that path and it "just works": it takes precedence over the
 * bundled fallbacks below with NO code change (this component always probes the
 * drop-in path first).
 *
 * ── Resolution order (first that loads wins) ────────────────────────────────
 * SSR renders the first candidate; the browser falls through via <img onError>:
 *   1. /logos/games/<family>.svg        (owner drop-in — primary)
 *   2. /logos/games/<family>.png        (owner drop-in — raster)
 *   3. bundled known asset (see KNOWN_ASSET — ships in the repo today)
 *   4. the per-family emoji glyph on a subtle brand-gradient tile (never blank)
 *
 * The game's brand colour is always kept for a soft glow/ring behind the mark so
 * the tile still looks designed even before an official logo is dropped in, and
 * terraria (no bundled asset yet) simply shows its emoji until the owner adds
 * public/logos/games/terraria.svg.
 */

import { useState } from "react";

/** Per-family display name, emoji fallback glyph, and brand gradient stops. */
export const GAME_VISUAL: Record<
  string,
  { name: string; glyph: string; from: string; to: string }
> = {
  minecraft: { name: "Minecraft", glyph: "⛏️", from: "#3b6d1f", to: "#6aab3a" },
  valheim: { name: "Valheim", glyph: "🪓", from: "#284c6f", to: "#4a86b8" },
  rust: { name: "Rust", glyph: "🔧", from: "#8a3b1e", to: "#cd6a37" },
  palworld: { name: "Palworld", glyph: "🐾", from: "#0f6f69", to: "#25c0b4" },
  cs2: { name: "Counter-Strike 2", glyph: "🎯", from: "#8a5a12", to: "#e0a63a" },
  terraria: { name: "Terraria", glyph: "🌳", from: "#3a5a2a", to: "#7aa441" },
  ark: { name: "ARK: Survival Evolved", glyph: "🦖", from: "#4a3a1e", to: "#b07a2e" },
  satisfactory: { name: "Satisfactory", glyph: "🏭", from: "#8a5a12", to: "#e6952a" },
  projectzomboid: { name: "Project Zomboid", glyph: "🧟", from: "#3a1e1e", to: "#8a3b3b" },
  sdtd: { name: "7 Days to Die", glyph: "🪓", from: "#4a2a12", to: "#a85a2a" },
  vrising: { name: "V Rising", glyph: "🩸", from: "#3a121e", to: "#a01e3b" },
  enshrouded: { name: "Enshrouded", glyph: "🌫️", from: "#1e2a3a", to: "#3b6a8a" },
  factorio: { name: "Factorio", glyph: "🏭", from: "#6b3410", to: "#d9791f" },
  gmod: { name: "Garry's Mod", glyph: "🧰", from: "#2a2a4a", to: "#5a5a8a" },
  conan: { name: "Conan Exiles", glyph: "🗡️", from: "#6b3a1e", to: "#b8763a" },
  unturned: { name: "Unturned", glyph: "🏝️", from: "#1e4a3a", to: "#3a8a6a" },
  theforest: { name: "The Forest", glyph: "🌲", from: "#14260f", to: "#2e5a1f" },
  sonsoftheforest: { name: "Sons of the Forest", glyph: "🪚", from: "#14261a", to: "#2e5a3a" },
  bedrock: { name: "Minecraft Bedrock", glyph: "🧱", from: "#3b6d1f", to: "#6aab3a" },
  // ── Wave 3 (2026-08-31) — real key-art landed in public/games/art/, so these
  //    get an on-brand gradient tile immediately instead of falling through to
  //    the generic NEUTRAL "🎮 Game" placeholder. ──
  dragonwilds: { name: "RuneScape: Dragonwilds", glyph: "🐉", from: "#4c2a7a", to: "#a855f7" },
  sunkenland: { name: "Sunkenland", glyph: "🌊", from: "#0e4f6b", to: "#22d3ee" },
  abioticfactor: { name: "Abiotic Factor", glyph: "🧪", from: "#3b3f8a", to: "#6366f1" },
  corekeeper: { name: "Core Keeper", glyph: "🪨", from: "#4a2f7a", to: "#c084fc" },
  icarus: { name: "Icarus", glyph: "🚀", from: "#0b4a63", to: "#38bdf8" },
  // ── Wave 4 (2026-08-31) — real key-art landed in public/games/art/. ──
  arkasa: { name: "ARK: Survival Ascended", glyph: "🦕", from: "#123a52", to: "#38bdf8" },
  soulmask: { name: "Soulmask", glyph: "🎭", from: "#1e2a4a", to: "#22d3ee" },
  dst: { name: "Don't Starve Together", glyph: "🔥", from: "#7a2a1e", to: "#f97316" },
  vintagestory: { name: "Vintage Story", glyph: "🏺", from: "#4a3620", to: "#7aa441" },
  necesse: { name: "Necesse", glyph: "🏘️", from: "#1e5a7a", to: "#38bdf8" },
  tf2: { name: "Team Fortress 2", glyph: "🎩", from: "#5a3a1e", to: "#cd6a37" },
  l4d2: { name: "Left 4 Dead 2", glyph: "🔫", from: "#2e2a0a", to: "#a8891e" },
};

/** Neutral fallback for an unknown family id. */
const NEUTRAL = { name: "Game", glyph: "🎮", from: "#334155", to: "#64748b" };

/**
 * Best currently-bundled asset per family (fallback #3). These ship in the repo
 * today (public/games/*) and give a real logo on staging BEFORE the owner drops
 * official files into public/logos/games/. Terraria has no bundled asset, so it
 * falls through to the emoji glyph.
 */
const KNOWN_ASSET: Record<string, string> = {
  minecraft: "/games/minecraft.svg",
  cs2: "/games/cs2.svg",
  rust: "/games/rust.png",
  palworld: "/games/palworld.png",
  valheim: "/games/valheim.png",
  // Real Steam-sourced logo art landed 2026-08-31 (public/games/art/). Dragonwilds
  // has no separate logo file (hero/poster only), so it falls through to the
  // emoji glyph above instead.
  sunkenland: "/games/art/sunkenland_logo.png",
  abioticfactor: "/games/art/abioticfactor_logo.png",
  corekeeper: "/games/art/corekeeper_logo.png",
  icarus: "/games/art/icarus_logo.png",
  // Wave 4 (2026-08-31), same rationale as Wave 3 above.
  arkasa: "/games/art/ark-survival-ascended_logo.png",
  soulmask: "/games/art/soulmask_logo.png",
  dst: "/games/art/dst_logo.png",
  vintagestory: "/games/art/vintagestory_logo.png",
  necesse: "/games/art/necesse_logo.png",
  tf2: "/games/art/tf2_logo.png",
  l4d2: "/games/art/l4d2_logo.png",
};

/**
 * Families whose supplied wordmark is LIGHT/white (needs a dark tile). Everything
 * else is treated as a dark logo and gets a light tile. Based on the actual
 * owner-supplied assets; adjust if a logo file is swapped for a differently-toned one.
 */
const LIGHT_MARK = new Set(["valheim", "cs2", "arkasa", "soulmask", "l4d2"]);

export function GameLogo({
  family,
  size = 48,
  className = "",
}: {
  family: string;
  /** Tile edge length in px. Default 48. */
  size?: number;
  className?: string;
}) {
  const visual = GAME_VISUAL[family] ?? NEUTRAL;

  // Candidate srcs in resolution order. Owner drop-in first, bundled asset last.
  // Owner drop-ins live in /logos/games/. They uploaded PNGs, so render the .png
  // FIRST (it exists for all six families → correct SSR image, no 404/broken-image
  // flash), then an optional .svg override, then the bundled /games/* fallback.
  const candidates = [
    `/logos/games/${family}.png`,
    `/logos/games/${family}.svg`,
    KNOWN_ASSET[family],
  ].filter(Boolean) as string[];

  const [idx, setIdx] = useState(0);
  const exhausted = idx >= candidates.length;
  const src = candidates[idx];
  const pad = Math.max(4, Math.round(size * 0.16));

  return (
    <span
      className={`relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-xl border border-white/10 ${className}`}
      style={{
        width: size,
        height: size,
        // Emoji tile gets the full brand gradient. A real logo needs CONTRAST:
        // most game wordmarks are DARK (Minecraft/Rust/Palworld/Terraria) and were
        // invisible on the old dark frosted tile — they sit on a LIGHT tile now.
        // The few LIGHT/white wordmarks (Valheim, CS2) keep a dark tile so they read.
        // Both carry a soft brand glow so the row still looks designed.
        background: exhausted
          ? `linear-gradient(135deg, ${visual.from}, ${visual.to})`
          : LIGHT_MARK.has(family)
            ? "rgba(9,14,28,0.9)"
            : "#eef2f8",
        boxShadow: `0 0 ${Math.round(size * 0.55)}px -${Math.round(size * 0.3)}px ${visual.to}`,
      }}
    >
      {exhausted ? (
        <span aria-hidden style={{ fontSize: Math.round(size * 0.5), lineHeight: 1 }}>
          {visual.glyph}
        </span>
      ) : (
        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
        <img
          key={src}
          src={src}
          alt={`${visual.name} logo`}
          onError={() => setIdx((i) => i + 1)}
          style={{
            width: size - pad * 2,
            height: size - pad * 2,
            objectFit: "contain",
          }}
        />
      )}
    </span>
  );
}

