import Link from "next/link";

/* eslint-disable @next/next/no-img-element */

/**
 * The Nxeon icon mark (brand PNG).
 *
 * Served from /nx-mark.png, NOT /icon.png: `app/icon.png` is Next.js's
 * reserved file-based metadata convention and already owns the /icon.png
 * route (it renders the site favicon). A same-named file in public/ collides
 * with that route — Next.js errors "A conflicting public file and page file
 * was found for path /icon.png" and 500s in dev, and even where prod happens
 * to let the public file win, that precedence is undocumented and can change
 * across Next versions. Keep this asset on its own path.
 */
export function NxMark({ size = 36 }: { id?: string; size?: number }) {
  return (
    <img
      src="/nx-mark.png"
      alt="Nxeon"
      height={size}
      style={{ height: size, width: "auto" }}
      className="select-none object-contain"
    />
  );
}

/** Full brand lockup (mark + wordmark), linking home. */
export function NxLogo({ size = 44 }: { id?: string; size?: number }) {
  return (
    <Link href="/" className="flex items-center" aria-label="Nxeon home">
      <img
        src="/logo.png"
        alt="Nxeon"
        height={size}
        style={{ height: size, width: "auto" }}
        className="select-none object-contain"
      />
    </Link>
  );
}

