=== gen-freemc-art.mjs header ===
/**
 * Hand-authored SVG -> JPEG art generator for the free-Minecraft game-type
 * cards + the dashboard top-card hero.
 *
 * All artwork here is ORIGINAL geometric/voxel illustration in the Nxeon
 * palette. Nothing is traced from, or reproduces, any Mojang/Minecraft asset
 * or character design.
 *
 * Palette anchors:
 *   navy    #0a0e1a -> #0f1420
 *   violet  #6f47f5 / #8b5cf6
 *   cyan    #06b6d4 / blue #3b82f6
 * Warm accents (sunset orange/amber) are used where the brief calls for them.
 */
import sharp from "sharp";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const OUT = process.argv[2] || "/opt/nxeon-wt-freemcredesign/public/games/art";
mkdirSync(OUT, { recursive: true });

const CARD_W = 800;
const CARD_H = 1000;

/* ------------------------------------------------------------------ utils */

function rng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

const f = (n) => Number(n.toFixed(2));

/** Scattered blocky "pixel dust" — small axis-aligned squares, the texture
 *  that ties every one of these scenes to the voxel language. */
function pixelDust({ seed, count, w, h, y0 = 0, y1 = h, color, minS = 2, maxS = 7, opacity = 0.5 }) {
  const r = rng(seed);
  let out = "";
  for (let i = 0; i < count; i++) {
    const s = minS + r() * (maxS - minS);
    const x = r() * w;
    const y = y0 + r() * (y1 - y0);
    const o = opacity * (0.25 + r() * 0.75);
    out += `<rect x="${f(x)}" y="${f(y)}" width="${f(s)}" height="${f(s)}" fill="${color}" opacity="${f(o)}"/>`;
  }
  return out;
}

function stars({ seed, count, w, h, color = "#dbeafe" }) {
  const r = rng(seed);
  let out = "";
  for (let i = 0; i < count; i++) {
    const s = r() < 0.15 ? 3 : 2;
    out += `<rect x="${f(r() * w)}" y="${f(r() * h)}" width="${s}" height="${s}" fill="${color}" opacity="${f(0.15 + r() * 0.6)}"/>`;
  }
  return out;
}

